 	ret = amlogic_thermal_enable(pdata);
 
 	return ret;
@@ -363,6 +465,8 @@ static int amlogic_thermal_suspend(struct device *dev)
 	struct amlogic_thermal *data = dev_get_drvdata(dev);
 
 	amlogic_thermal_disable(data);
+	if (data->data->has_sysclk)
